## Kotlin 클라이언트 구현

```kotlin
import org.elasticsearch.action.search.SearchRequest
import org.elasticsearch.index.query.QueryBuilders
import org.elasticsearch.index.query.functionscore.FunctionScoreQueryBuilder
import org.elasticsearch.index.query.functionscore.ScoreFunctionBuilders
import org.elasticsearch.search.builder.SearchSourceBuilder
import org.elasticsearch.search.rescore.QueryRescorerBuilder

fun buildProductSearchQuery(
    keyword: String,
    windowSize: Int = 200
): SearchRequest {
    // 1단계: BM25 기본 쿼리
    val baseQuery = QueryBuilders.multiMatchQuery(keyword)
        .field("product_name", 3.0f)
        .field("description", 1.0f)
        .field("brand", 2.0f)
        .type(MultiMatchQueryBuilder.Type.BEST_FIELDS)
        .tieBreaker(0.3f)

    // Function Score 래핑
    val functionScoreQuery = QueryBuilders.functionScoreQuery(
        baseQuery,
        arrayOf(
            // 판매량 반영
            FunctionScoreQueryBuilder.FilterFunctionBuilder(
                ScoreFunctionBuilders.fieldValueFactorFunction("sales_count")
                    .modifier(FieldValueFactorFunction.Modifier.LOG1P)
                    .missing(0.0)
            ),
            // 날짜 감쇠
            FunctionScoreQueryBuilder.FilterFunctionBuilder(
                ScoreFunctionBuilders.gaussDecayFunction(
                    "created_at", "now", "30d", "7d", 0.5
                )
            )
        )
    ).scoreMode(FunctionScoreQuery.ScoreMode.SUM)
     .boostMode(CombineFunction.MULTIPLY)

    // 2단계: Phrase Rescore
    val phraseRescore = QueryRescorerBuilder(
        QueryBuilders.matchPhraseQuery("product_name", keyword).slop(2)
    ).setQueryWeight(0.7f)
     .setRescoreQueryWeight(1.2f)
     .windowSize(windowSize)

    // 검색 요청 조립
    val searchSource = SearchSourceBuilder()
        .query(functionScoreQuery)
        .addRescorer(phraseRescore)
        .size(20)

    return SearchRequest("products").source(searchSource)
}

fun main() {
    val request = buildProductSearchQuery("무선 블루투스 이어폰")
    // client.search(request, RequestOptions.DEFAULT)
    println("검색 쿼리 빌드 완료: ${request.indices().joinToString()}")
}
```

